export const BUNDLED_MIGRATIONS = [
  {
    "version": "0001",
    "name": "0001_baseline_schema.sql",
    "sql": "CREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\n\nDO $$ BEGIN\n  CREATE TYPE user_role AS ENUM ('Admin', 'Manager', 'Sales User', 'Viewer');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE product_status AS ENUM ('Draft', 'Published', 'Archived');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE lead_status AS ENUM ('New', 'Contacted', 'Qualified', 'Proposal Sent', 'Closed', 'Lost');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE integration_status AS ENUM ('Active', 'Inactive', 'Error');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE audit_action AS ENUM ('create', 'update', 'delete', 'login', 'logout', 'publish', 'archive', 'upload', 'download');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE product_asset_type AS ENUM ('thumbnail', 'image', 'model', 'usdz_model', 'document', 'qr_png', 'qr_svg');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nCREATE TABLE IF NOT EXISTS organizations (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  name text NOT NULL,\n  slug text,\n  website text,\n  logo_url text,\n  primary_color text DEFAULT '#2563EB',\n  profile text,\n  is_verified boolean DEFAULT false,\n  ai_assist_enabled boolean DEFAULT false,\n  storage_quota_bytes bigint DEFAULT 5368709120,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE organizations ADD COLUMN IF NOT EXISTS slug text;\nALTER TABLE organizations ADD COLUMN IF NOT EXISTS is_verified boolean DEFAULT false;\nALTER TABLE organizations ADD COLUMN IF NOT EXISTS ai_assist_enabled boolean DEFAULT false;\nALTER TABLE organizations ADD COLUMN IF NOT EXISTS storage_quota_bytes bigint DEFAULT 5368709120;\nCREATE UNIQUE INDEX IF NOT EXISTS idx_organizations_slug ON organizations(slug) WHERE slug IS NOT NULL;\n\n\nCREATE TABLE IF NOT EXISTS users (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL,\n  name text NOT NULL,\n  email text NOT NULL UNIQUE,\n  phone text,\n  avatar_url text,\n  password_hash text NOT NULL,\n  role user_role NOT NULL DEFAULT 'Viewer',\n  reset_token_hash text,\n  reset_token_expires_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS products (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  category text NOT NULL,\n  description text,\n  status product_status NOT NULL DEFAULT 'Draft',\n  specs jsonb NOT NULL DEFAULT '{}'::jsonb,\n  image_url text,\n  model_url text,\n  document_url text,\n  video_url text,\n  usdz_url text,\n  is_public boolean NOT NULL DEFAULT false,\n  slug text,\n  public_url text,\n  thumbnail_asset_id uuid,\n  model_asset_id uuid,\n  usdz_asset_id uuid,\n  qr_code_id uuid,\n  dimensions jsonb,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE products ADD COLUMN IF NOT EXISTS is_public boolean NOT NULL DEFAULT false;\nALTER TABLE products ADD COLUMN IF NOT EXISTS slug text;\nALTER TABLE products ADD COLUMN IF NOT EXISTS public_url text;\nALTER TABLE products ADD COLUMN IF NOT EXISTS thumbnail_asset_id uuid;\nALTER TABLE products ADD COLUMN IF NOT EXISTS model_asset_id uuid;\nALTER TABLE products ADD COLUMN IF NOT EXISTS usdz_asset_id uuid;\nALTER TABLE products ADD COLUMN IF NOT EXISTS usdz_url text;\nALTER TABLE products ADD COLUMN IF NOT EXISTS dimensions jsonb;\nALTER TABLE products ADD COLUMN IF NOT EXISTS qr_code_id uuid;\nALTER TABLE products ADD COLUMN IF NOT EXISTS document_url text;\nALTER TABLE products ADD COLUMN IF NOT EXISTS video_url text;\n\nALTER TYPE product_asset_type ADD VALUE IF NOT EXISTS 'document';\nALTER TYPE product_asset_type ADD VALUE IF NOT EXISTS 'usdz_model';\nALTER TYPE product_asset_type ADD VALUE IF NOT EXISTS 'qr_png';\nALTER TYPE product_asset_type ADD VALUE IF NOT EXISTS 'qr_svg';\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_products_company_slug ON products(organization_id, slug) WHERE slug IS NOT NULL;\n\nCREATE TABLE IF NOT EXISTS files (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid REFERENCES products(id) ON DELETE SET NULL,\n  file_category text NOT NULL DEFAULT 'document' CHECK (file_category IN ('image', 'video', 'model', 'document')),\n  original_name text NOT NULL,\n  object_key text NOT NULL,\n  url text NOT NULL,\n  mime_type text NOT NULL,\n  size_bytes integer NOT NULL,\n  checksum_sha256 text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE files ADD COLUMN IF NOT EXISTS file_category text NOT NULL DEFAULT 'document';\nALTER TABLE files ADD COLUMN IF NOT EXISTS checksum_sha256 text;\nALTER TABLE files DROP CONSTRAINT IF EXISTS files_file_category_check;\nALTER TABLE files ADD CONSTRAINT files_file_category_check CHECK (file_category IN ('image', 'video', 'model', 'document'));\n\nCREATE TABLE IF NOT EXISTS product_assets (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n  asset_type product_asset_type NOT NULL,\n  original_name text NOT NULL,\n  file_name text NOT NULL,\n  file_path text NOT NULL,\n  public_url text NOT NULL,\n  mime_type text NOT NULL,\n  size_bytes integer NOT NULL,\n  checksum_sha256 text,\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE product_assets ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;\n\nCREATE TABLE IF NOT EXISTS catalogs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  status product_status NOT NULL DEFAULT 'Draft',\n  slug text NOT NULL UNIQUE,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  published_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE catalogs ADD COLUMN IF NOT EXISTS pdf_url text;\n\nCREATE TABLE IF NOT EXISTS catalog_products (\n  catalog_id uuid NOT NULL REFERENCES catalogs(id) ON DELETE CASCADE,\n  product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n  sort_order integer NOT NULL DEFAULT 0,\n  PRIMARY KEY (catalog_id, product_id)\n);\n\nCREATE TABLE IF NOT EXISTS qr_codes (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid NOT NULL UNIQUE REFERENCES products(id) ON DELETE CASCADE,\n  product_slug text NOT NULL,\n  target_url text NOT NULL,\n  png_asset_id uuid REFERENCES product_assets(id) ON DELETE SET NULL,\n  svg_asset_id uuid REFERENCES product_assets(id) ON DELETE SET NULL,\n  png_url text NOT NULL,\n  svg_url text NOT NULL,\n  generated_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS product_id uuid;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS product_slug text;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS png_asset_id uuid;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS svg_asset_id uuid;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS png_url text;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS svg_url text;\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS generated_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE qr_codes ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE qr_codes DROP CONSTRAINT IF EXISTS qr_codes_entity_type_check;\nALTER TABLE qr_codes DROP COLUMN IF EXISTS entity_type;\nALTER TABLE qr_codes DROP COLUMN IF EXISTS entity_id;\n\nCREATE TABLE IF NOT EXISTS leads (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid REFERENCES products(id) ON DELETE SET NULL,\n  catalog_id uuid REFERENCES catalogs(id) ON DELETE SET NULL,\n  name text NOT NULL,\n  email text NOT NULL,\n  phone text,\n  organization text,\n  company text,\n  designation text,\n  status lead_status NOT NULL DEFAULT 'New',\n  priority text NOT NULL DEFAULT 'Normal',\n  source text NOT NULL DEFAULT 'Catalog',\n  score integer NOT NULL DEFAULT 0,\n  notes text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS analytics_events (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid REFERENCES products(id) ON DELETE SET NULL,\n  catalog_id uuid REFERENCES catalogs(id) ON DELETE SET NULL,\n  lead_id uuid REFERENCES leads(id) ON DELETE SET NULL,\n  visitor_id text,\n  event_type text NOT NULL CHECK (event_type IN ('page_view', 'product_view', 'catalog_view', 'qr_scan', 'ar_launch', 'ar_session', 'lead_created', 'hotspot_view', 'animation_play')),\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS visitor_sessions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  visitor_id text NOT NULL,\n  lead_id uuid REFERENCES leads(id) ON DELETE SET NULL,\n  session_start timestamptz DEFAULT now(),\n  updated_at timestamptz DEFAULT now()\n);\n\nALTER TABLE analytics_events ADD COLUMN IF NOT EXISTS visitor_id text;\n\nALTER TABLE analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;\nALTER TABLE analytics_events ADD CONSTRAINT analytics_events_event_type_check\n  CHECK (event_type IN (\n    'page_view', 'product_view', 'catalog_view', 'catalog_generated', 'catalog_downloaded',\n    'product_visit_from_catalog', 'qr_scan_from_catalog', 'qr_scan', 'qr_landing', 'qr_preview', 'qr_download',\n    '3d_interaction', 'hotspot_click', 'hotspot_view', 'animation_play', 'blueprint_toggle',\n    'ar_launch', 'ar_session', 'ar_launch_attempt', 'ar_session_success', 'ar_unsupported_fallback',\n    'cta_quote_click', 'lead_form_submitted', 'dwell_time_ping', 'session_duration', 'lead_created',\n    'user_register', 'user_login', 'brochure_download', 'quote_request', 'time_spent', 'button_click', 'model_rotation', 'search', 'exit_intent', 'contact_sales', 'model_download'\n  ));\n\nCREATE TABLE IF NOT EXISTS product_animations (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  animation_key text NOT NULL,\n  description text,\n  sort_order integer NOT NULL DEFAULT 0,\n  duration_ms integer CHECK (duration_ms IS NULL OR duration_ms >= 0),\n  is_enabled boolean NOT NULL DEFAULT true,\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (product_id, animation_key)\n);\n\nCREATE TABLE IF NOT EXISTS product_hotspots (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  content text,\n  position jsonb NOT NULL,\n  action_type text CHECK (action_type IS NULL OR action_type IN ('info', 'document', 'video', 'quote', 'external_link')),\n  action_value text,\n  sort_order integer NOT NULL DEFAULT 0,\n  is_enabled boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS lead_activities (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  lead_id uuid NOT NULL REFERENCES leads(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  activity_type text NOT NULL CHECK (activity_type IN ('note', 'email', 'call', 'meeting', 'status_change', 'task')),\n  subject text,\n  body text,\n  due_at timestamptz,\n  completed_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS audit_logs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  details jsonb,\n  ip_address text,\n  user_agent text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS action text NOT NULL DEFAULT 'unknown';\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS entity_type text;\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS entity_id text;\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS details jsonb;\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS ip_address text;\nALTER TABLE audit_logs ADD COLUMN IF NOT EXISTS user_agent text;\n\nCREATE TABLE IF NOT EXISTS company_preferences (\n  organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,\n  onboarding_enabled boolean NOT NULL DEFAULT true,\n  default_brand_color text NOT NULL DEFAULT '#2563EB',\n  default_catalog_visibility text NOT NULL DEFAULT 'private' CHECK (default_catalog_visibility IN ('private', 'public')),\n  notification_preferences jsonb NOT NULL DEFAULT '{}'::jsonb,\n  appearance_preferences jsonb NOT NULL DEFAULT '{}'::jsonb,\n  feature_flags jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS support_tickets (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  category text NOT NULL CHECK (category IN ('FAQ', 'Contact Support', 'Report Issue', 'Feature Request', 'Documentation')),\n  subject text NOT NULL,\n  message text NOT NULL,\n  status text NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'In Progress', 'Resolved', 'Closed')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS notifications (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  body text,\n  notification_type text NOT NULL DEFAULT 'system',\n  read_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS integrations (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  provider text NOT NULL,\n  status integration_status NOT NULL DEFAULT 'Inactive',\n  config jsonb NOT NULL DEFAULT '{}'::jsonb,\n  secrets_ref text,\n  last_sync_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (organization_id, provider)\n);\n\n-- The user_sessions and user_devices tables have been removed to migrate to Supabase Auth.\n\n-- 2. Upgrade Notifications for Mobile Sync\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS is_read_mobile boolean NOT NULL DEFAULT false;\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS is_read_web boolean NOT NULL DEFAULT false;\nALTER TABLE notifications ADD COLUMN IF NOT EXISTS action_url text; -- Deep link target\n\n-- 3. Offline Sync Queue\nCREATE TABLE IF NOT EXISTS offline_sync_queue (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  device_id text NOT NULL,\n  entity_type text NOT NULL, -- 'analytics', 'lead', 'interaction'\n  operation text NOT NULL, -- 'create', 'update', 'delete'\n  payload jsonb NOT NULL,\n  status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Processed', 'Failed')),\n  error_message text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  processed_at timestamptz\n);\nCREATE INDEX IF NOT EXISTS idx_offline_sync_queue_status ON offline_sync_queue(user_id, status);\n\n\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- ZERO TRUST SECURITY & ENTERPRISE AUTHENTICATION SCHEMA\n-- ─────────────────────────────────────────────────────────────────────────────\n\n-- 1. Expand User Roles\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Super Admin';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Company Admin';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Sales Executive';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Support Executive';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Marketing';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Analytics Viewer';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Read Only';\nALTER TYPE user_role ADD VALUE IF NOT EXISTS 'Customer';\n\n-- 2. Expand Users Table for Google Auth & MFA\nALTER TABLE users ADD COLUMN IF NOT EXISTS google_id text UNIQUE;\nALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_enabled boolean NOT NULL DEFAULT false;\nALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_secret text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS last_login_at timestamptz;\nALTER TABLE users ADD COLUMN IF NOT EXISTS last_login_ip text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS failed_login_attempts integer NOT NULL DEFAULT 0;\nALTER TABLE users ADD COLUMN IF NOT EXISTS locked_until timestamptz;\nALTER TABLE users ADD COLUMN IF NOT EXISTS designation text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS department text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS bio text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS banner_url text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS website text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS location text;\nALTER TABLE users ADD COLUMN IF NOT EXISTS social_links jsonb;\nALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified boolean NOT NULL DEFAULT false;\n\n-- 3. Session Management Table (Zero Trust tracking)\n-- (Schema unified in main definitions above)\n-- CREATE INDEX IF NOT EXISTS idx_user_sessions_user ON user_sessions(user_id);\n-- CREATE INDEX IF NOT EXISTS idx_user_sessions_token ON user_sessions(refresh_token_hash);\n\n-- 4. Audit Logs (Enterprise Compliance)\n-- (Schema unified in main definitions above)\nCREATE INDEX IF NOT EXISTS idx_audit_logs_company ON audit_logs(organization_id);\nCREATE INDEX IF NOT EXISTS idx_audit_logs_user ON audit_logs(user_id);\nCREATE INDEX IF NOT EXISTS idx_audit_logs_action ON audit_logs(action);\nCREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at);\n\n-- 5. Security Alerts (Threat Detection)\nDO $$ BEGIN\n  CREATE TYPE alert_severity AS ENUM ('Low', 'Medium', 'High', 'Critical');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nCREATE TABLE IF NOT EXISTS security_alerts (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  alert_type text NOT NULL, -- e.g., 'Brute Force Attempt', 'New Device Login'\n  severity alert_severity NOT NULL DEFAULT 'Medium',\n  is_resolved boolean NOT NULL DEFAULT false,\n  details jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  resolved_at timestamptz,\n  resolved_by uuid REFERENCES users(id) ON DELETE SET NULL\n);\nCREATE INDEX IF NOT EXISTS idx_security_alerts_company ON security_alerts(organization_id, is_resolved);\n\nCREATE TABLE IF NOT EXISTS organization_members (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role user_role NOT NULL DEFAULT 'Viewer',\n  joined_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(organization_id, user_id)\n);\n\nCREATE TABLE IF NOT EXISTS organization_domains (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  domain text NOT NULL,\n  verification_status text NOT NULL DEFAULT 'Pending',\n  verification_token text,\n  verified_at timestamptz,\n  auto_join_enabled boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(domain)\n);\n\nALTER TABLE leads ADD COLUMN IF NOT EXISTS priority text NOT NULL DEFAULT 'Medium';\nALTER TABLE leads ADD COLUMN IF NOT EXISTS assigned_to uuid REFERENCES users(id) ON DELETE SET NULL;\n\nCREATE TABLE IF NOT EXISTS lead_intelligence (\n  lead_id uuid PRIMARY KEY REFERENCES leads(id) ON DELETE CASCADE,\n  behavior_score integer NOT NULL DEFAULT 0,\n  total_time_spent integer NOT NULL DEFAULT 0,\n  total_pages_visited integer NOT NULL DEFAULT 0,\n  total_products_viewed integer NOT NULL DEFAULT 0,\n  total_qr_scans integer NOT NULL DEFAULT 0,\n  total_ar_sessions integer NOT NULL DEFAULT 0,\n  total_downloads integer NOT NULL DEFAULT 0,\n  lead_category text NOT NULL DEFAULT 'Cold',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- OTP Verifications\nCREATE TABLE IF NOT EXISTS otp_verifications (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid REFERENCES users(id) ON DELETE CASCADE,\n  email text NOT NULL,\n  purpose text NOT NULL CHECK (purpose IN ('account_verify', 'email_verify', 'password_reset', 'invitation', 'owner_transfer', 'security_update', 'domain_verify', 'sensitive_action')),\n  otp_hash text NOT NULL,\n  attempts_count integer NOT NULL DEFAULT 0,\n  max_attempts integer NOT NULL DEFAULT 5,\n  expires_at timestamptz NOT NULL,\n  verified_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_otp_email_purpose ON otp_verifications(email, purpose, verified_at);\n\n-- Organization Invitations\nCREATE TABLE IF NOT EXISTS organization_invitations (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  email text NOT NULL,\n  role user_role NOT NULL DEFAULT 'Sales User',\n  token text NOT NULL UNIQUE,\n  invited_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'expired', 'revoked')),\n  expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'),\n  accepted_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (organization_id, email)\n);\n\n-- Publishing Access & Approval Workflow\nCREATE TABLE IF NOT EXISTS publishing_access (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  product_id uuid REFERENCES products(id) ON DELETE CASCADE,\n  catalog_id uuid REFERENCES catalogs(id) ON DELETE CASCADE,\n  visibility text NOT NULL DEFAULT 'PUBLIC' CHECK (visibility IN ('PUBLIC', 'ORGANIZATION', 'RESTRICTED')),\n  approval_status text NOT NULL DEFAULT 'PUBLISHED' CHECK (approval_status IN ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'PUBLISHED')),\n  published_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  published_at timestamptz NOT NULL DEFAULT now(),\n  restricted_user_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  restricted_team_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  expires_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT check_entity CHECK ((product_id IS NOT NULL AND catalog_id IS NULL) OR (product_id IS NULL AND catalog_id IS NOT NULL))\n);\n\n-- Notification Preferences\nCREATE TABLE IF NOT EXISTS notification_preferences (\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  email_notifications jsonb NOT NULL DEFAULT '{\"security\": true, \"leads\": true, \"publishing\": true, \"billing\": true, \"weekly_report\": true}'::jsonb,\n  in_app_notifications jsonb NOT NULL DEFAULT '{\"security\": true, \"leads\": true, \"publishing\": true, \"billing\": true, \"team\": true}'::jsonb,\n  weekly_report_enabled boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (organization_id, user_id)\n);\n\n-- Weekly Reports Log\nCREATE TABLE IF NOT EXISTS weekly_reports (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  period_start timestamptz NOT NULL,\n  period_end timestamptz NOT NULL,\n  metrics_summary jsonb NOT NULL,\n  recipients jsonb NOT NULL DEFAULT '[]'::jsonb,\n  sent_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Automation Rules\nCREATE TABLE IF NOT EXISTS automation_rules (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  event_type text NOT NULL,\n  conditions jsonb NOT NULL DEFAULT '{}'::jsonb,\n  audience_roles jsonb NOT NULL DEFAULT '[\"Admin\", \"Owner\"]'::jsonb,\n  channel text NOT NULL DEFAULT 'both' CHECK (channel IN ('email', 'in_app', 'both')),\n  is_active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- VAULT ASSET SCHEMA\n-- ─────────────────────────────────────────────────────────────────────────────\nDO $$ BEGIN\n  CREATE TYPE asset_status AS ENUM ('Processing', 'Ready', 'Warning', 'Failed');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE TYPE asset_visibility AS ENUM ('Private', 'Organization', 'Public');\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nCREATE TABLE IF NOT EXISTS vault_collections (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  schema_fields jsonb NOT NULL DEFAULT '[]'::jsonb,\n  is_deleted boolean NOT NULL DEFAULT false,\n  deleted_at timestamptz,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_templates (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  schema jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_assets (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  category text,\n  tags jsonb NOT NULL DEFAULT '[]'::jsonb,\n  type text NOT NULL,\n  original_name text NOT NULL,\n  storage_key text NOT NULL,\n  public_url text NOT NULL,\n  mime_type text NOT NULL,\n  size_bytes integer NOT NULL,\n  checksum_sha256 text,\n  status asset_status NOT NULL DEFAULT 'Processing',\n  visibility asset_visibility NOT NULL DEFAULT 'Organization',\n  thumbnail_url text,\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  custom_fields jsonb NOT NULL DEFAULT '{}'::jsonb,\n  connected_apps jsonb NOT NULL DEFAULT '[\"Spatial Hub\", \"Omni Studio\"]'::jsonb,\n  is_deleted boolean NOT NULL DEFAULT false,\n  deleted_at timestamptz,\n  collection_id uuid REFERENCES vault_collections(id) ON DELETE SET NULL,\n  template_id uuid REFERENCES vault_templates(id) ON DELETE SET NULL,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_asset_versions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  asset_id uuid NOT NULL REFERENCES vault_assets(id) ON DELETE CASCADE,\n  version_number integer NOT NULL,\n  original_name text NOT NULL,\n  storage_key text NOT NULL,\n  public_url text NOT NULL,\n  mime_type text NOT NULL,\n  size_bytes integer NOT NULL,\n  checksum_sha256 text,\n  change_description text,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_records (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  collection_id uuid NOT NULL REFERENCES vault_collections(id) ON DELETE CASCADE,\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  data jsonb NOT NULL DEFAULT '{}'::jsonb,\n  asset_id uuid REFERENCES vault_assets(id) ON DELETE SET NULL,\n  status text NOT NULL DEFAULT 'Active',\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_audit_logs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  user_name text,\n  action text NOT NULL,\n  target_type text NOT NULL,\n  target_id uuid,\n  target_name text,\n  details jsonb DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS vault_processing_jobs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  job_type text NOT NULL,\n  asset_name text NOT NULL,\n  status text NOT NULL DEFAULT 'Completed',\n  progress_pct integer NOT NULL DEFAULT 100,\n  started_at timestamptz NOT NULL DEFAULT now(),\n  completed_at timestamptz DEFAULT now(),\n  error_message text\n);\n\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- SPATIAL HUB PERSONAL CONTENT SCHEMA\n-- ─────────────────────────────────────────────────────────────────────────────\n\nCREATE TABLE IF NOT EXISTS saved_items (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  content_id uuid NOT NULL,\n  content_type text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(user_id, content_id)\n);\n\nCREATE TABLE IF NOT EXISTS liked_items (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  content_id uuid NOT NULL,\n  content_type text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(user_id, content_id)\n);\n\nCREATE TABLE IF NOT EXISTS hub_subscriptions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  plan text NOT NULL,\n  status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Canceled', 'Past_Due', 'Trialing')),\n  start_date timestamptz NOT NULL DEFAULT now(),\n  renewal_date timestamptz,\n  enterprise_access boolean NOT NULL DEFAULT false,\n  features jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(organization_id)\n);\n\n-- ─────────────────────────────────────────────────────────────────────────────\n-- COMMERCIAL READINESS & BILLING SCHEMA\n-- ─────────────────────────────────────────────────────────────────────────────\n\nCREATE TABLE IF NOT EXISTS usage_counters (\n  organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,\n  products_count integer NOT NULL DEFAULT 0,\n  catalogs_count integer NOT NULL DEFAULT 0,\n  models_count integer NOT NULL DEFAULT 0,\n  storage_bytes_used bigint NOT NULL DEFAULT 0,\n  team_members_count integer NOT NULL DEFAULT 1,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS billing_customers (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id) ON DELETE CASCADE,\n  razorpay_customer_id text NOT NULL UNIQUE,\n  email text NOT NULL,\n  name text NOT NULL,\n  phone text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS billing_events (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  provider text NOT NULL DEFAULT 'razorpay',\n  provider_event_id text NOT NULL,\n  event_type text NOT NULL,\n  payload jsonb NOT NULL,\n  processed_at timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(provider, provider_event_id)\n);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  razorpay_payment_id text UNIQUE,\n  razorpay_order_id text,\n  amount_inr numeric(10, 2) NOT NULL DEFAULT 0,\n  currency text NOT NULL DEFAULT 'INR',\n  status text NOT NULL DEFAULT 'captured',\n  method text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS orders (\n  id text PRIMARY KEY,\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  plan_id text NOT NULL,\n  billing_cycle text NOT NULL CHECK (billing_cycle IN ('monthly', 'yearly')),\n  amount_paise integer NOT NULL,\n  amount_inr numeric(10, 2) NOT NULL,\n  currency text NOT NULL DEFAULT 'INR',\n  status text NOT NULL DEFAULT 'created' CHECK (status IN ('created', 'paid', 'failed')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS password_reset_tokens (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  token_hash text NOT NULL UNIQUE,\n  expires_at timestamptz NOT NULL,\n  used_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS invoices (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  invoice_number text NOT NULL UNIQUE,\n  plan_id text NOT NULL,\n  amount_inr numeric(10, 2) NOT NULL DEFAULT 0,\n  tax_inr numeric(10, 2) NOT NULL DEFAULT 0,\n  status text NOT NULL DEFAULT 'paid',\n  period_start timestamptz NOT NULL DEFAULT now(),\n  period_end timestamptz NOT NULL DEFAULT (now() + interval '30 days'),\n  pdf_url text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS organization_billing_info (\n  organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,\n  billing_name text NOT NULL,\n  billing_email text NOT NULL,\n  phone text,\n  tax_id text,\n  address_line1 text,\n  address_line2 text,\n  city text,\n  state text,\n  postal_code text,\n  country text NOT NULL DEFAULT 'India',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS enterprise_requests (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  company_name text NOT NULL,\n  work_email text NOT NULL,\n  contact_name text NOT NULL,\n  phone text,\n  expected_product_count integer DEFAULT 100,\n  expected_catalog_usage integer DEFAULT 50,\n  team_size integer DEFAULT 10,\n  required_features jsonb DEFAULT '[]'::jsonb,\n  message text,\n  status text NOT NULL DEFAULT 'pending',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ============================================================================\n-- Phase S1: Identity, Sessions, and Multi-Factor Authentication\n-- ============================================================================\n\nALTER TABLE users ADD COLUMN IF NOT EXISTS token_version integer NOT NULL DEFAULT 1;\n\nCREATE TABLE IF NOT EXISTS sessions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  family_id uuid NOT NULL DEFAULT uuid_generate_v4(),\n  token_hash text NOT NULL UNIQUE,\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  ua_hash text,\n  ip_prefix text,\n  expires_at timestamptz NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  revoked_at timestamptz,\n  replaced_by uuid REFERENCES sessions(id) ON DELETE SET NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_sessions_token_hash ON sessions(token_hash);\nCREATE INDEX IF NOT EXISTS idx_sessions_family_id ON sessions(family_id);\nCREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);\n\nCREATE TABLE IF NOT EXISTS user_mfa (\n  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,\n  secret_encrypted text NOT NULL,\n  is_enabled boolean NOT NULL DEFAULT false,\n  scratch_codes jsonb NOT NULL DEFAULT '[]'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ============================================================================\n-- Section: Personal Hub Tables (04-add-personal-hub-tables)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS saved_items (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  content_id uuid NOT NULL,\n  content_type text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(user_id, content_id)\n);\n\nCREATE TABLE IF NOT EXISTS liked_items (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  content_id uuid NOT NULL,\n  content_type text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(user_id, content_id)\n);\n\nCREATE TABLE IF NOT EXISTS hub_subscriptions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  plan text NOT NULL,\n  status text NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Canceled', 'Past_Due', 'Trialing')),\n  start_date timestamptz NOT NULL DEFAULT now(),\n  renewal_date timestamptz,\n  enterprise_access boolean NOT NULL DEFAULT false,\n  features jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(organization_id)\n);\n\n-- ============================================================================\n-- Section: Spatial Experiences & Studio Projects\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS spatial_experiences (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  slug text NOT NULL UNIQUE,\n  description text,\n  status text NOT NULL DEFAULT 'Draft',\n  vault_asset_id uuid REFERENCES vault_assets(id) ON DELETE SET NULL,\n  pinned_version_number integer NOT NULL DEFAULT 1,\n  scene_config jsonb NOT NULL DEFAULT '{\"camera\": {\"fov\": 45, \"position\": [0, 1.5, 3], \"target\": [0, 0, 0]}, \"environment\": {\"preset\": \"studio\", \"exposure\": 1.0, \"contactShadow\": true, \"reflection\": 0.2}, \"ground\": {\"showGrid\": true, \"shadowOpacity\": 0.4}}'::jsonb,\n  hotspots jsonb NOT NULL DEFAULT '[]'::jsonb,\n  animation_config jsonb NOT NULL DEFAULT '{\"activeClip\": null, \"playbackSpeed\": 1.0, \"explodedViewFactor\": 0.0, \"parts\": []}'::jsonb,\n  blueprint_config jsonb NOT NULL DEFAULT '{\"enabled\": false, \"dimensions\": {\"length\": 0, \"width\": 0, \"height\": 0, \"unit\": \"mm\"}, \"callouts\": []}'::jsonb,\n  ar_config jsonb NOT NULL DEFAULT '{\"scale\": 1.0, \"placement\": \"floor\", \"allowSnapshot\": true, \"ctaText\": \"Request Quote\"}'::jsonb,\n  published_snapshot jsonb,\n  published_at timestamptz,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS studio_projects (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  name text NOT NULL,\n  description text,\n  project_type text NOT NULL DEFAULT 'Application',\n  status text NOT NULL DEFAULT 'Draft',\n  thumbnail text,\n  version integer NOT NULL DEFAULT 1,\n  last_published_version integer,\n  visibility text NOT NULL DEFAULT 'Organization',\n  product_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  vault_asset_ids jsonb NOT NULL DEFAULT '[]'::jsonb,\n  project_document jsonb NOT NULL DEFAULT '{\"screens\": [], \"components\": [], \"component_tree\": [], \"variables\": [], \"data_sources\": [], \"bindings\": [], \"actions\": [], \"logic\": [], \"theme\": {}, \"settings\": {}}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  published_at timestamptz\n);\n\nCREATE TABLE IF NOT EXISTS studio_project_versions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  project_id uuid NOT NULL REFERENCES studio_projects(id) ON DELETE CASCADE,\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  version_number integer NOT NULL,\n  author_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  change_summary text,\n  project_document jsonb NOT NULL,\n  published_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ============================================================================\n-- Section: Flow Automation Engine (I3DION Flow)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS flows (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  owner_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  name text NOT NULL,\n  description text DEFAULT '',\n  status text NOT NULL DEFAULT 'draft',\n  version integer NOT NULL DEFAULT 1,\n  last_published_version integer,\n  trigger_type text NOT NULL DEFAULT 'manual',\n  trigger_config jsonb NOT NULL DEFAULT '{}'::jsonb,\n  flow_definition jsonb NOT NULL DEFAULT '{\"trigger\": {\"id\": \"trig_1\", \"type\": \"manual\", \"label\": \"Manual Trigger\", \"config\": {}}, \"nodes\": [], \"edges\": [], \"variables\": [], \"settings\": {\"concurrency\": 5, \"timeoutSeconds\": 120, \"retentionDays\": 30}}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  published_at timestamptz\n);\n\nCREATE TABLE IF NOT EXISTS flow_versions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  flow_id uuid NOT NULL REFERENCES flows(id) ON DELETE CASCADE,\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  version_number integer NOT NULL,\n  author_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  change_summary text,\n  flow_definition jsonb NOT NULL,\n  published_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (flow_id, version_number)\n);\n\nCREATE TABLE IF NOT EXISTS flow_runs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  flow_id uuid NOT NULL REFERENCES flows(id) ON DELETE CASCADE,\n  flow_version integer NOT NULL DEFAULT 1,\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  triggered_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  status text NOT NULL DEFAULT 'pending',\n  trigger_payload jsonb NOT NULL DEFAULT '{}'::jsonb,\n  step_results jsonb NOT NULL DEFAULT '[]'::jsonb,\n  error text,\n  started_at timestamptz NOT NULL DEFAULT now(),\n  completed_at timestamptz\n);\n\nCREATE TABLE IF NOT EXISTS flow_event_outbox (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  event_type text NOT NULL,\n  payload jsonb NOT NULL DEFAULT '{}'::jsonb,\n  status text NOT NULL DEFAULT 'pending',\n  attempts integer NOT NULL DEFAULT 0,\n  last_error text,\n  destination_url text,\n  response_status integer,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  processed_at timestamptz\n);\n\nCREATE INDEX IF NOT EXISTS idx_flows_org_id ON flows(organization_id);\nCREATE INDEX IF NOT EXISTS idx_flow_runs_flow_id ON flow_runs(flow_id);\nCREATE INDEX IF NOT EXISTS idx_flow_runs_org_id ON flow_runs(organization_id);\nCREATE INDEX IF NOT EXISTS idx_flow_outbox_status ON flow_event_outbox(status);\n\n-- ============================================================================\n-- Section: Lens Intelligence Engine\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS intelligence_sessions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  session_id text NOT NULL UNIQUE,\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  lead_id uuid REFERENCES leads(id) ON DELETE SET NULL,\n  visitor_id text,\n  application_id text DEFAULT 'hub',\n  project_id text,\n  started_at timestamptz NOT NULL DEFAULT now(),\n  ended_at timestamptz,\n  last_active_at timestamptz NOT NULL DEFAULT now(),\n  duration_seconds integer DEFAULT 0,\n  apps_opened jsonb DEFAULT '[]'::jsonb,\n  products_viewed jsonb DEFAULT '[]'::jsonb,\n  experiences_opened jsonb DEFAULT '[]'::jsonb,\n  searches_performed jsonb DEFAULT '[]'::jsonb,\n  interactions_count integer DEFAULT 0,\n  cta_clicks_count integer DEFAULT 0,\n  engagement_depth_score numeric DEFAULT 0.0,\n  metadata jsonb DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS user_behavior_profiles (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  user_id uuid REFERENCES users(id) ON DELETE CASCADE,\n  visitor_id text,\n  lead_id uuid REFERENCES leads(id) ON DELETE SET NULL,\n  category_weights jsonb DEFAULT '{}'::jsonb,\n  industry_weights jsonb DEFAULT '{}'::jsonb,\n  product_interactions jsonb DEFAULT '{}'::jsonb,\n  experience_interactions jsonb DEFAULT '{}'::jsonb,\n  frequently_used_apps jsonb DEFAULT '{}'::jsonb,\n  engagement_score numeric DEFAULT 0.0,\n  intent_score numeric DEFAULT 0.0,\n  lead_classification text DEFAULT 'COLD',\n  last_activity_at timestamptz DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS algorithm_configs (\n  organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,\n  recency_decay_half_life_days integer DEFAULT 14,\n  frequency_weight numeric DEFAULT 1.5,\n  recency_weight numeric DEFAULT 2.0,\n  depth_weight numeric DEFAULT 1.2,\n  intent_weight numeric DEFAULT 3.0,\n  lead_cold_threshold numeric DEFAULT 24.0,\n  lead_warm_threshold numeric DEFAULT 49.0,\n  lead_hot_threshold numeric DEFAULT 74.0,\n  lead_high_intent_threshold numeric DEFAULT 100.0,\n  custom_rules jsonb DEFAULT '[]'::jsonb,\n  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS intelligence_audit_logs (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE,\n  actor_id uuid REFERENCES users(id) ON DELETE SET NULL,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  details jsonb DEFAULT '{}'::jsonb,\n  ip_address text,\n  user_agent text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_intel_events_org ON analytics_events(organization_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_intel_events_user ON analytics_events(user_id) WHERE user_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS idx_intel_events_session ON analytics_events(session_id) WHERE session_id IS NOT NULL;\nCREATE INDEX IF NOT EXISTS idx_intel_events_type ON analytics_events(event_type);\nCREATE INDEX IF NOT EXISTS idx_intel_sessions_org ON intelligence_sessions(organization_id, last_active_at DESC);\nCREATE INDEX IF NOT EXISTS idx_intel_behavior_org ON user_behavior_profiles(organization_id);\n"
  },
  {
    "version": "0002",
    "name": "0002_enable_rls_tenant_tables.sql",
    "sql": "-- =============================================================================\n-- Migration: 0002_enable_rls_tenant_tables.sql\n-- Description: Enable PostgreSQL Row-Level Security (RLS) on all multi-tenant tables\n-- Requirements: SEC-02 (Tenant Isolation via withTenant & Database RLS)\n-- =============================================================================\n\n-- 1. Create Application Role (Non-Superuser) to ensure RLS policies are strictly enforced\nDO $$ \nBEGIN \n  BEGIN\n    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'i3dion_app') THEN \n      CREATE ROLE i3dion_app NOINHERIT; \n    END IF; \n  EXCEPTION WHEN OTHERS THEN\n    -- Hosted Postgres (Neon, Supabase pooler) may disallow role creation; continue gracefully\n    RAISE NOTICE 'Skipping CREATE ROLE i3dion_app: %', SQLERRM;\n  END;\n\n  BEGIN\n    GRANT USAGE ON SCHEMA public TO i3dion_app;\n    GRANT ALL ON ALL TABLES IN SCHEMA public TO i3dion_app;\n    GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO i3dion_app;\n    ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO i3dion_app;\n    ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO i3dion_app;\n  EXCEPTION WHEN OTHERS THEN\n    RAISE NOTICE 'Skipping GRANT TO i3dion_app: %', SQLERRM;\n  END;\nEND $$;\n\n-- 2. Enable RLS and Tenant Isolation Policy across all Organization-scoped tables\nDO $$\nDECLARE\n  tbl text;\n  tenant_tables text[] := ARRAY[\n    'vault_assets', 'vault_collections', 'vault_templates', 'vault_processing_jobs',\n    'vault_audit_logs', 'vault_records', 'vault_schemas', 'vault_schema_fields',\n    'vault_saved_views', 'vault_shares', 'vault_approval_workflows', 'vault_enquiries',\n    'studio_projects', 'studio_project_versions', 'catalogs', 'products', 'product_assets',\n    'product_relationships', 'product_animations', 'product_hotspots', 'product_assets_map',\n    'flows', 'flow_runs', 'flow_versions', 'flow_event_outbox',\n    'organization_members', 'organization_invitations', 'organization_domains',\n    'organization_billing_info', 'leads', 'lead_activities', 'analytics_events',\n    'audit_logs', 'support_tickets', 'notifications', 'notification_preferences',\n    'subscriptions', 'billing_customers', 'payments', 'invoices', 'orders',\n    'spatial_experiences', 'integrations', 'security_alerts', 'files'\n  ];\nBEGIN\n  FOREACH tbl IN ARRAY tenant_tables LOOP\n    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = tbl) THEN\n      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', tbl);\n      EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', tbl);\n      EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_policy ON %I', tbl);\n      EXECUTE format('\n        CREATE POLICY tenant_isolation_policy ON %I\n        FOR ALL\n        USING (\n          NULLIF(current_setting(''app.org_id'', true), '''')::uuid IS NULL\n          OR organization_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid\n        )\n        WITH CHECK (\n          NULLIF(current_setting(''app.org_id'', true), '''')::uuid IS NULL\n          OR organization_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid\n        )\n      ', tbl);\n    END IF;\n  END LOOP;\nEND $$;\n\n-- 3. Row-Level Security for organizations table (checks primary key id)\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'organizations') THEN\n    ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;\n    ALTER TABLE organizations FORCE ROW LEVEL SECURITY;\n    DROP POLICY IF EXISTS tenant_isolation_policy ON organizations;\n    CREATE POLICY tenant_isolation_policy ON organizations\n      FOR ALL\n      USING (\n        NULLIF(current_setting('app.org_id', true), '')::uuid IS NULL\n        OR id = NULLIF(current_setting('app.org_id', true), '')::uuid\n      )\n      WITH CHECK (\n        NULLIF(current_setting('app.org_id', true), '')::uuid IS NULL\n        OR id = NULLIF(current_setting('app.org_id', true), '')::uuid\n      );\n  END IF;\nEND $$;\n\n-- 4. Row-Level Security for users table\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'users') THEN\n    ALTER TABLE users ENABLE ROW LEVEL SECURITY;\n    ALTER TABLE users FORCE ROW LEVEL SECURITY;\n    DROP POLICY IF EXISTS tenant_isolation_policy ON users;\n    CREATE POLICY tenant_isolation_policy ON users\n      FOR ALL\n      USING (\n        NULLIF(current_setting('app.org_id', true), '')::uuid IS NULL\n        OR organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid\n      )\n      WITH CHECK (\n        NULLIF(current_setting('app.org_id', true), '')::uuid IS NULL\n        OR organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid\n      );\n  END IF;\nEND $$;\n"
  },
  {
    "version": "0003",
    "name": "0003_catalog_player_pwa_qr.sql",
    "sql": "-- Migration 0003: Catalog Player PWA, Short Links, QR Campaigns & Server-Side Audience Filtering\n-- Enforces Row-Level Security for catalog_links table.\n\nCREATE TABLE IF NOT EXISTS catalog_links (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n    catalog_id UUID REFERENCES catalogs(id) ON DELETE CASCADE,\n    project_id UUID REFERENCES studio_projects(id) ON DELETE CASCADE,\n    short_code VARCHAR(32) NOT NULL UNIQUE,\n    label TEXT NOT NULL DEFAULT 'Default Link',\n    campaign TEXT NOT NULL DEFAULT 'Direct',\n    audience_role VARCHAR(32) NOT NULL DEFAULT 'public',\n    allowed_fields JSONB DEFAULT '[]'::jsonb,\n    hidden_fields JSONB DEFAULT '[]'::jsonb,\n    password_hash VARCHAR(255),\n    expires_at TIMESTAMPTZ,\n    dealer_info JSONB DEFAULT '{}'::jsonb,\n    qr_svg TEXT,\n    qr_png_url TEXT,\n    visits_count INTEGER NOT NULL DEFAULT 0,\n    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\nCREATE INDEX IF NOT EXISTS idx_catalog_links_short_code ON catalog_links(short_code);\nCREATE INDEX IF NOT EXISTS idx_catalog_links_org ON catalog_links(organization_id);\nCREATE INDEX IF NOT EXISTS idx_catalog_links_catalog ON catalog_links(catalog_id);\n\n-- Enable and Force Row Level Security\nALTER TABLE catalog_links ENABLE ROW LEVEL SECURITY;\nALTER TABLE catalog_links FORCE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS tenant_isolation_catalog_links ON catalog_links;\nCREATE POLICY tenant_isolation_catalog_links ON catalog_links\n    FOR ALL\n    TO i3dion_app\n    USING (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid)\n    WITH CHECK (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid);\n\n-- Ensure leads table supports RFQ metadata, intent and message\nALTER TABLE leads ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb;\nALTER TABLE leads ADD COLUMN IF NOT EXISTS intent TEXT DEFAULT 'quote';\nALTER TABLE leads ADD COLUMN IF NOT EXISTS message TEXT;\nCREATE INDEX IF NOT EXISTS idx_leads_metadata_idempotency ON leads USING gin (metadata);\n\n-- Section 4.6 Whitelisted Catalog Player Events constraint update\nALTER TABLE analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;\nALTER TABLE analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (\n  event_type = ANY (ARRAY[\n    'page_view'::text, 'product_view'::text, 'catalog_view'::text, 'catalog_generated'::text, 'catalog_downloaded'::text,\n    'product_visit_from_catalog'::text, 'qr_scan_from_catalog'::text, 'qr_scan'::text, 'qr_landing'::text, 'qr_preview'::text,\n    'qr_download'::text, '3d_interaction'::text, 'hotspot_click'::text, 'hotspot_view'::text, 'animation_play'::text,\n    'blueprint_toggle'::text, 'ar_launch'::text, 'ar_session'::text, 'ar_launch_attempt'::text, 'ar_session_success'::text,\n    'ar_unsupported_fallback'::text, 'cta_quote_click'::text, 'lead_form_submitted'::text, 'dwell_time_ping'::text,\n    'session_duration'::text, 'lead_created'::text, 'user_register'::text, 'user_login'::text, 'brochure_download'::text,\n    'quote_request'::text, 'time_spent'::text, 'button_click'::text, 'model_rotation'::text, 'search'::text,\n    'exit_intent'::text, 'contact_sales'::text, 'model_download'::text,\n    'catalog.viewed'::text, 'page.viewed'::text, 'product.viewed'::text, 'hotspot.opened'::text,\n    'viewer.3d_interacted'::text, 'ar.launch_attempted'::text, 'ar.launch_succeeded'::text,\n    'basket.item_added'::text, 'rfq.submitted'::text, 'download.pdf'::text, 'share.clicked'::text\n  ])\n);\n\n\n"
  },
  {
    "version": "0004",
    "name": "0004_durable_flow_queue_and_checkpoints.sql",
    "sql": "-- ============================================================================\n-- Migration 0004: Durable Flow Queue, Checkpoints, Timers & Idempotency (Phase P2)\n-- Implements Master Prompt v5.0 §6, §9 & BUG-01/02/03\n-- ============================================================================\n\n-- 1. Extend flow_runs table with checkpointing & durable timer columns\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS current_step_index integer NOT NULL DEFAULT 0;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS execution_context jsonb NOT NULL DEFAULT '{}'::jsonb;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS resume_at timestamptz;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS attempts integer NOT NULL DEFAULT 0;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 3;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS dead_letter_reason text;\nALTER TABLE flow_runs ADD COLUMN IF NOT EXISTS last_heartbeat timestamptz;\n\n-- 2. Create durable flow_queue table for PostgreSQL FOR UPDATE SKIP LOCKED job execution\nCREATE TABLE IF NOT EXISTS flow_queue (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  flow_id uuid NOT NULL REFERENCES flows(id) ON DELETE CASCADE,\n  run_id uuid NOT NULL REFERENCES flow_runs(id) ON DELETE CASCADE,\n  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'waiting_delay', 'waiting_approval', 'completed', 'failed', 'dead_letter')),\n  priority integer NOT NULL DEFAULT 0,\n  attempts integer NOT NULL DEFAULT 0,\n  max_attempts integer NOT NULL DEFAULT 3,\n  next_run_at timestamptz NOT NULL DEFAULT now(),\n  locked_at timestamptz,\n  locked_by text,\n  last_error text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Index for high-throughput concurrency and SKIP LOCKED worker polling\nCREATE INDEX IF NOT EXISTS idx_flow_queue_claim ON flow_queue(status, next_run_at, priority DESC, created_at ASC);\nCREATE INDEX IF NOT EXISTS idx_flow_queue_tenant ON flow_queue(organization_id, status);\nCREATE INDEX IF NOT EXISTS idx_flow_queue_run_id ON flow_queue(run_id);\n\n-- 3. Create flow_step_checkpoints table for strict step-level idempotency\nCREATE TABLE IF NOT EXISTS flow_step_checkpoints (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  run_id uuid NOT NULL REFERENCES flow_runs(id) ON DELETE CASCADE,\n  step_id text NOT NULL,\n  idempotency_key text NOT NULL UNIQUE,\n  step_index integer NOT NULL DEFAULT 0,\n  status text NOT NULL DEFAULT 'succeeded',\n  output jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_flow_checkpoints_run_step ON flow_step_checkpoints(run_id, step_id);\nCREATE INDEX IF NOT EXISTS idx_flow_checkpoints_idempotency ON flow_step_checkpoints(idempotency_key);\n\n-- 4. Enable Row Level Security (RLS) on newly created tables\nALTER TABLE flow_queue ENABLE ROW LEVEL SECURITY;\nALTER TABLE flow_step_checkpoints ENABLE ROW LEVEL SECURITY;\n\nDO $$ BEGIN\n  CREATE POLICY flow_queue_tenant_isolation ON flow_queue\n    FOR ALL\n    USING (organization_id = current_setting('app.org_id', true)::uuid)\n    WITH CHECK (organization_id = current_setting('app.org_id', true)::uuid);\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n\nDO $$ BEGIN\n  CREATE POLICY flow_step_checkpoints_tenant_isolation ON flow_step_checkpoints\n    FOR ALL\n    USING (organization_id = current_setting('app.org_id', true)::uuid)\n    WITH CHECK (organization_id = current_setting('app.org_id', true)::uuid);\nEXCEPTION WHEN duplicate_object THEN null; END $$;\n"
  },
  {
    "version": "0005",
    "name": "0005_vault_dataverse_sharepoint.sql",
    "sql": "-- =============================================================================\n-- Migration: 0005_vault_dataverse_sharepoint.sql\n-- Description: Vault as Dataverse + SharePoint (Phase P3)\n-- Requirements: Schema designer, 16 typed columns, relationships, folders,\n--               major/minor versions, retention labels, asset_usage, hash-chained audit.\n-- =============================================================================\n\n-- 1. Create vault_folders for SharePoint-style document library hierarchy\nCREATE TABLE IF NOT EXISTS vault_folders (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  parent_id uuid REFERENCES vault_folders(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  path text NOT NULL,\n  created_by uuid REFERENCES users(id) ON DELETE SET NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_vault_folders_org_path ON vault_folders(organization_id, path);\n\n-- 2. Add folder_id and retention_label to vault_assets if not exists\nALTER TABLE vault_assets\n  ADD COLUMN IF NOT EXISTS folder_id uuid REFERENCES vault_folders(id) ON DELETE SET NULL,\n  ADD COLUMN IF NOT EXISTS retention_label text;\n\n-- 3. Create asset_usage table to track multi-product asset references (Studio/Engine/Flow)\nCREATE TABLE IF NOT EXISTS asset_usage (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  asset_id uuid NOT NULL REFERENCES vault_assets(id) ON DELETE CASCADE,\n  version_id uuid REFERENCES vault_asset_versions(id) ON DELETE SET NULL,\n  consumer_type text NOT NULL, -- 'catalog', 'scene', 'page', 'flow'\n  consumer_id text NOT NULL,\n  consumer_name text,\n  context jsonb DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_asset_usage_org_asset ON asset_usage(organization_id, asset_id);\nCREATE INDEX IF NOT EXISTS idx_asset_usage_consumer ON asset_usage(consumer_type, consumer_id);\n\n-- 4. Create vault_relationships table for Dataverse-style relational integrity\nCREATE TABLE IF NOT EXISTS vault_relationships (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  source_collection_id uuid NOT NULL REFERENCES vault_collections(id) ON DELETE CASCADE,\n  target_collection_id uuid NOT NULL REFERENCES vault_collections(id) ON DELETE CASCADE,\n  relationship_type text NOT NULL CHECK (relationship_type IN ('lookup', 'one_to_many', 'many_to_many')),\n  on_delete text NOT NULL DEFAULT 'restrict' CHECK (on_delete IN ('restrict', 'cascade', 'set_null')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_vault_relationships_source ON vault_relationships(organization_id, source_collection_id);\nCREATE INDEX IF NOT EXISTS idx_vault_relationships_target ON vault_relationships(organization_id, target_collection_id);\n\n-- 5. Extend vault_schema_fields to support advanced Dataverse columns\nALTER TABLE vault_schema_fields\n  ADD COLUMN IF NOT EXISTS formula_definition text,\n  ADD COLUMN IF NOT EXISTS rollup_definition jsonb,\n  ADD COLUMN IF NOT EXISTS lookup_collection_id uuid REFERENCES vault_collections(id) ON DELETE SET NULL,\n  ADD COLUMN IF NOT EXISTS lookup_field_name text,\n  ADD COLUMN IF NOT EXISTS audience_restricted boolean DEFAULT false,\n  ADD COLUMN IF NOT EXISTS allowed_roles text[] DEFAULT ARRAY['Admin', 'Manager', 'Sales']::text[];\n\n-- 6. Extend vault_audit_logs with cryptographic hash chaining\nALTER TABLE vault_audit_logs\n  ADD COLUMN IF NOT EXISTS previous_hash text,\n  ADD COLUMN IF NOT EXISTS current_hash text;\n\nCREATE INDEX IF NOT EXISTS idx_vault_audit_logs_hash ON vault_audit_logs(organization_id, created_at ASC);\nCREATE INDEX IF NOT EXISTS idx_vault_records_data_gin ON vault_records USING gin (data);\n\n-- 7. Enable RLS and Tenant Isolation on new tables\nDO $$\nDECLARE\n  tbl text;\n  new_tenant_tables text[] := ARRAY[\n    'vault_folders', 'asset_usage', 'vault_relationships'\n  ];\nBEGIN\n  FOREACH tbl IN ARRAY new_tenant_tables LOOP\n    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = tbl) THEN\n      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', tbl);\n      EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', tbl);\n      EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_policy ON %I', tbl);\n      EXECUTE format('\n        CREATE POLICY tenant_isolation_policy ON %I\n        FOR ALL\n        USING (\n          NULLIF(current_setting(''app.org_id'', true), '''')::uuid IS NULL\n          OR organization_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid\n        )\n        WITH CHECK (\n          NULLIF(current_setting(''app.org_id'', true), '''')::uuid IS NULL\n          OR organization_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid\n        )\n      ', tbl);\n    END IF;\n  END LOOP;\nEND $$;\n"
  },
  {
    "version": "0006",
    "name": "0006_engine_scene_document_and_circuits.sql",
    "sql": "-- =============================================================================\n-- Migration: 0006_engine_scene_document_and_circuits.sql\n-- Description: Omni Engine Scene Document, Keyframes & Circuits IR (Phase P8)\n-- Requirements: Non-destructive scene document, optimistic revision locking (409),\n--               circuit visual graph definition and compiled IR persistence.\n-- =============================================================================\n\nALTER TABLE spatial_experiences\n  ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 1,\n  ADD COLUMN IF NOT EXISTS scene_document jsonb DEFAULT '{}'::jsonb,\n  ADD COLUMN IF NOT EXISTS circuits_graph jsonb DEFAULT '{\"nodes\": [], \"edges\": []}'::jsonb,\n  ADD COLUMN IF NOT EXISTS circuits_ir jsonb DEFAULT '{\"entrypoints\": {}, \"handlers\": {}}'::jsonb;\n\nCREATE INDEX IF NOT EXISTS idx_spatial_experiences_org_rev \n  ON spatial_experiences(organization_id, revision);\n\n-- Whitelist experience.published in analytics_events\nALTER TABLE analytics_events DROP CONSTRAINT IF EXISTS analytics_events_event_type_check;\nALTER TABLE analytics_events ADD CONSTRAINT analytics_events_event_type_check CHECK (\n  event_type = ANY (ARRAY[\n    'page_view'::text, 'product_view'::text, 'catalog_view'::text, 'catalog_generated'::text, 'catalog_downloaded'::text,\n    'product_visit_from_catalog'::text, 'qr_scan_from_catalog'::text, 'qr_scan'::text, 'qr_landing'::text, 'qr_preview'::text,\n    'qr_download'::text, '3d_interaction'::text, 'hotspot_click'::text, 'hotspot_view'::text, 'animation_play'::text,\n    'blueprint_toggle'::text, 'ar_launch'::text, 'ar_session'::text, 'ar_launch_attempt'::text, 'ar_session_success'::text,\n    'ar_unsupported_fallback'::text, 'cta_quote_click'::text, 'lead_form_submitted'::text, 'dwell_time_ping'::text,\n    'session_duration'::text, 'lead_created'::text, 'user_register'::text, 'user_login'::text, 'brochure_download'::text,\n    'quote_request'::text, 'time_spent'::text, 'button_click'::text, 'model_rotation'::text, 'search'::text,\n    'exit_intent'::text, 'contact_sales'::text, 'model_download'::text,\n    'catalog.viewed'::text, 'page.viewed'::text, 'product.viewed'::text, 'hotspot.opened'::text,\n    'viewer.3d_interacted'::text, 'ar.launch_attempted'::text, 'ar.launch_succeeded'::text,\n    'basket.item_added'::text, 'rfq.submitted'::text, 'download.pdf'::text, 'share.clicked'::text,\n    'experience.published'::text\n  ])\n);\n\n"
  },
  {
    "version": "0007",
    "name": "0007_lens_live_and_presenter_sessions.sql",
    "sql": "-- =============================================================================\n-- Migration: 0007_lens_live_and_presenter_sessions.sql\n-- Description: Lens Live Analytics, AI Assist Opt-in, and Presenter Mode (Phase P9)\n-- Requirements: Presenter sessions with real-time sync, AI assist strict opt-in toggle,\n--               and index optimization for dealer and QR campaign rollups.\n-- =============================================================================\n\n-- 1. AI Assist Opt-in column on organizations (Decision D-10: opt-in, zero customer data training)\nALTER TABLE organizations\n  ADD COLUMN IF NOT EXISTS ai_assist_enabled boolean NOT NULL DEFAULT false;\n\n-- 2. Presenter Mode Sessions (Innovation Item 11)\nCREATE TABLE IF NOT EXISTS presenter_sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,\n  experience_id uuid REFERENCES spatial_experiences(id) ON DELETE SET NULL,\n  session_code text NOT NULL UNIQUE,\n  host_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  active_slide integer NOT NULL DEFAULT 0,\n  camera_orbit jsonb NOT NULL DEFAULT '[0, 0, 5]'::jsonb,\n  active_variant text,\n  active_hotspot text,\n  exploded_factor numeric NOT NULL DEFAULT 0,\n  is_active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_presenter_sessions_code ON presenter_sessions(session_code);\nCREATE INDEX IF NOT EXISTS idx_presenter_sessions_org ON presenter_sessions(organization_id, is_active);\n\n-- Enable RLS on presenter_sessions\nALTER TABLE presenter_sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE presenter_sessions FORCE ROW LEVEL SECURITY;\n\nDO $$ BEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies WHERE tablename = 'presenter_sessions' AND policyname = 'tenant_isolation_presenter_sessions'\n  ) THEN\n    CREATE POLICY tenant_isolation_presenter_sessions ON presenter_sessions\n      AS PERMISSIVE FOR ALL\n      USING (organization_id = NULLIF(current_setting('app.org_id', true), '')::uuid);\n  END IF;\nEND $$;\n\n-- 3. Extend vault_approval_workflows to support unified cross-product approvals (Phase P9)\nALTER TABLE vault_approval_workflows DROP CONSTRAINT IF EXISTS vault_approval_workflows_approval_status_check;\nALTER TABLE vault_approval_workflows ADD CONSTRAINT vault_approval_workflows_approval_status_check CHECK (\n  approval_status = ANY (ARRAY['Draft'::text, 'Submitted'::text, 'Under Review'::text, 'Approved'::text, 'Rejected'::text, 'PENDING_REVIEW'::text, 'APPROVED'::text, 'REJECTED'::text])\n);\n\nALTER TABLE vault_approval_workflows DROP CONSTRAINT IF EXISTS vault_approval_workflows_resource_type_check;\nALTER TABLE vault_approval_workflows ADD CONSTRAINT vault_approval_workflows_resource_type_check CHECK (\n  resource_type = ANY (ARRAY['asset'::text, 'record'::text, 'catalog'::text, 'schema'::text, 'flow'::text, 'quote'::text])\n);\n\n"
  },
  {
    "version": "0008",
    "name": "0008_spatial_hub_provenance_and_tiers.sql",
    "sql": "-- Migration: 0008_spatial_hub_provenance_and_tiers.sql\r\n-- Description: Adds model provenance, license metadata, tiered asset URLs, and indexes for Spatial Hub.\r\n-- Demotes legacy fake/unlicensed models from public feed.\r\n\r\n-- 1. Add provenance, license, and asset tiers to products\r\nALTER TABLE products \r\n  ADD COLUMN IF NOT EXISTS license_spdx TEXT[] DEFAULT ARRAY['CC0-1.0']::TEXT[],\r\n  ADD COLUMN IF NOT EXISTS license_artist TEXT,\r\n  ADD COLUMN IF NOT EXISTS license_owner TEXT,\r\n  ADD COLUMN IF NOT EXISTS license_source_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS attribution_required BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS commercial_use BOOLEAN NOT NULL DEFAULT true,\r\n  ADD COLUMN IF NOT EXISTS is_demo_model BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS preview_model_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS poster_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS full_model_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS original_model_url TEXT;\r\n\r\n-- 2. Add license and tier columns to vault_assets\r\nALTER TABLE vault_assets\r\n  ADD COLUMN IF NOT EXISTS license_spdx TEXT[] DEFAULT ARRAY['CC0-1.0']::TEXT[],\r\n  ADD COLUMN IF NOT EXISTS license_artist TEXT,\r\n  ADD COLUMN IF NOT EXISTS license_owner TEXT,\r\n  ADD COLUMN IF NOT EXISTS license_source_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS attribution_required BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS commercial_use BOOLEAN NOT NULL DEFAULT true,\r\n  ADD COLUMN IF NOT EXISTS is_demo_model BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS preview_url TEXT,\r\n  ADD COLUMN IF NOT EXISTS poster_url TEXT;\r\n\r\n-- 3. Create index for fast hub feed querying\r\nCREATE INDEX IF NOT EXISTS idx_products_hub_feed \r\n  ON products (is_public, status, created_at DESC)\r\n  WHERE is_public = true AND status = 'Published';\r\n\r\nCREATE INDEX IF NOT EXISTS idx_products_slug \r\n  ON products (slug);\r\n\r\n-- 4. Demote legacy unverified/renamed models from public visibility (HUB-01..03)\r\nUPDATE products\r\nSET is_public = false,\r\n    status = 'Archived',\r\n    updated_at = now()\r\nWHERE model_url LIKE '/models/model_%.gltf';\r\n\r\n-- 5. Ensure Showcase Organization exists for demonstration models\r\nALTER TABLE organizations\r\n  ADD COLUMN IF NOT EXISTS slug TEXT,\r\n  ADD COLUMN IF NOT EXISTS is_verified BOOLEAN DEFAULT false;\r\n\r\nINSERT INTO organizations (id, name, slug, profile, website, is_verified, created_at, updated_at)\r\nVALUES (\r\n  'e0000000-0000-0000-0000-000000000001',\r\n  'I3DION Showcase',\r\n  'i3dion-showcase',\r\n  'Official demonstration and reference models for the I3DION Spatial Hub ecosystem. All models carry verifiable CC0 or CC-BY open source licenses.',\r\n  'https://i3dion.com',\r\n  true,\r\n  now(),\r\n  now()\r\n)\r\nON CONFLICT (id) DO UPDATE SET\r\n  name = EXCLUDED.name,\r\n  profile = EXCLUDED.profile,\r\n  is_verified = true,\r\n  updated_at = now();\r\n\r\n"
  },
  {
    "version": "0009",
    "name": "0009_qr_shortlinks_and_attribution.sql",
    "sql": "-- Migration: 0009_qr_shortlinks_and_attribution.sql\r\n-- Description: Enhances qr_codes table with >= 96-bit short links, pause/expiry/password controls, campaign attribution, and visit counters.\r\n\r\n-- 1. Add short link and attribution columns to qr_codes\r\nALTER TABLE qr_codes\r\n  ALTER COLUMN product_id DROP NOT NULL,\r\n  ALTER COLUMN png_url DROP NOT NULL,\r\n  ALTER COLUMN svg_url DROP NOT NULL,\r\n  ALTER COLUMN generated_at SET DEFAULT now();\r\n\r\nALTER TABLE qr_codes\r\n  ADD COLUMN IF NOT EXISTS short_code VARCHAR(32) UNIQUE,\r\n  ADD COLUMN IF NOT EXISTS title TEXT,\r\n  ADD COLUMN IF NOT EXISTS campaign TEXT,\r\n  ADD COLUMN IF NOT EXISTS utm_source TEXT,\r\n  ADD COLUMN IF NOT EXISTS utm_medium TEXT,\r\n  ADD COLUMN IF NOT EXISTS is_paused BOOLEAN NOT NULL DEFAULT false,\r\n  ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ,\r\n  ADD COLUMN IF NOT EXISTS password_hash TEXT,\r\n  ADD COLUMN IF NOT EXISTS visits_count INTEGER NOT NULL DEFAULT 0,\r\n  ADD COLUMN IF NOT EXISTS last_visited_at TIMESTAMPTZ;\r\n\r\n-- 2. Create index for fast O(1) short code resolution\r\nCREATE INDEX IF NOT EXISTS idx_qr_codes_short_code \r\n  ON qr_codes (short_code);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_qr_codes_org_campaign \r\n  ON qr_codes (organization_id, campaign);\r\n\r\n"
  },
  {
    "version": "0010",
    "name": "0010_spatial_hub_moderation_and_reports.sql",
    "sql": "-- Migration: 0010_spatial_hub_moderation_and_reports.sql\r\n-- Description: Creates moderation_reports table for community content reporting and abuse prevention (HUB-15).\r\n\r\nCREATE TABLE IF NOT EXISTS moderation_reports (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  reporter_id UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  reporter_email TEXT,\r\n  entity_type VARCHAR(32) NOT NULL,\r\n  entity_id VARCHAR(64) NOT NULL,\r\n  reason TEXT NOT NULL,\r\n  details TEXT,\r\n  status VARCHAR(32) NOT NULL DEFAULT 'pending',\r\n  resolution_notes TEXT,\r\n  resolved_by UUID REFERENCES users(id) ON DELETE SET NULL,\r\n  resolved_at TIMESTAMPTZ,\r\n  ip_address TEXT,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n);\r\n\r\n-- Indexes for efficient moderation review and querying\r\nCREATE INDEX IF NOT EXISTS idx_moderation_reports_entity \r\n  ON moderation_reports (entity_type, entity_id);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_moderation_reports_status \r\n  ON moderation_reports (status, created_at DESC);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_moderation_reports_reporter \r\n  ON moderation_reports (reporter_id);\r\n\r\n"
  },
  {
    "version": "0011",
    "name": "0011_repair_analytics_event_identity_columns.sql",
    "sql": "-- Repair older deployments that recorded the baseline schema before\r\n-- analytics_events gained the identity/session columns used by Lens indexes.\r\n-- This is additive and safe to run against both new and existing databases.\r\n\r\nALTER TABLE analytics_events\r\n  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES users(id) ON DELETE SET NULL,\r\n  ADD COLUMN IF NOT EXISTS session_id text;\r\n\r\nCREATE INDEX IF NOT EXISTS idx_intel_events_user\r\n  ON analytics_events(user_id) WHERE user_id IS NOT NULL;\r\n\r\nCREATE INDEX IF NOT EXISTS idx_intel_events_session\r\n  ON analytics_events(session_id) WHERE session_id IS NOT NULL;\r\n"
  }
];
